import sys
import math

def count_fruits(x, y):
    while x >= 1 + y and y >= 1:
        diff = math.gcd(x, y)
        x /= diff
        y /= diff
    return x, y

def is_possible(x, y):
    (x, y) = count_fruits(x, y)
    needs = math.reduce(lambda a, b: b * a, (x for _ in range(y)), 1)
    total_needed = x * y / gcd(x, y)
    return total_needed <= needs

def get_good_solution(x, y):
    (x, y) = count_fruits(x, y)
    if y == 1:
        return (x - 1) // 2
    (x, y) = count_fruits(x, y)
    if y == 1:
        return 1
    card = -1
    x_times = x // math.gcd(x, y)
    while x_times >= 1:
        card += 1
        x_times = (x_times - 1) // 2
    final = [0 for _ in range(card)]
    slice_size = [x // y for _ in range(card)]
    for i in range(card):
        for j in range(slice_size[i] + 1):
            final[i] = i + 1
    return "".join(map(str, final))

if __name__ == "__main__":
    (x, y) = map(int, sys.stdin.readline().strip().split())
    if not is_possible(x, y):
        print("Impossible")
        sys.exit()

    init_string = get_good_solution(x, y)
    print(init_string)
