def binomial_coeff(n, r):
    return power(comb(n, r), MOD - 2, MOD)

def count_mirror_positions(patterns):
    n, m = len(patterns), len(patterns[0])
    dp = [[[0] * 2 for _ in range(m)] for _ in range(n)]

    for i in range(n):
        for j in range(m):
            dp[i][j][0] = dp[i][j][1] = 2 ** len(patterns)

    for i in range(n):
        for j in range(m):
            if patterns[i][j] == '*':
                dp[i][j][0] = dp[i][j][1] = 0
            elif patterns[i][j] == '\\':
                dp[i][j][0] = 1
                dp[i][j][1] = 2 ** len(patterns) - 1
            elif patterns[i][j] == '/':
                dp[i][j][1] = 1
                dp[i][j][0] = 2 ** len(patterns) - 1
            else:
                continue

    for i in range(1, n):
        for j in range(m):
            for d in range(2):
                if patterns[i][j] == '*':
                    dp[i][j][d] = dp[i][j][1 - d] % MOD
                else:
                    dp[i][j][d] = dp[i-1][j][d] * dp[i][j][1 - d] % MOD

    total_mirror = (2 ** n + 2 ** m - 3) % MOD
    solution = 0

    for i in range(m):
        solution = (solution + dp[n-1][i][1] * binomial_coeff(total_mirror, n-1) % MOD) % MOD

    total_mirror -= 2
    solution = solution * binomial_coeff(total_mirror, n) % MOD

    return solution

