def count_tours(k, l, r):
    MOD = 10**9 + 7

    # Calculate all possible lengths for tours
    lengths = [0] * (k + 1)
    max_length = 0
    for l, r in range(1, 30, 2):
        max_length = max(l, r)
        lengths[max_length] += 1

    # Handle case when k <= max_length
    if k <= max_length:
        result = 1
        for i in range(k):
            result = (result * (2 ** i)) % MOD
        return result

    # Handle k > max_length
    else:
        # Get the maximum length of all lengths
        max_length_other, others = max(lengths), []
        for l, r in enumerate(lengths):
            if l >= max_length_other:
                others.append(l)
                max_length_other = l

        # Calculate result
        dp = [1] * k
        for j in range(1, max_length + 1):
            for nxt_length in others:
                if j + nxt_length - 1 <= r and j <= max_length:
                    dp[j] = (dp[j] * (max_length + 1 - j - nxt_length + 1)) % MOD

        return dp[k-1]

