def diameter(n: int, s: str) -> int:
    graph = defaultdict(dict)
    adjacency = defaultdict(list)

    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if abs(i - j) == 1:
                adjacency[i].append(j)
                adjacency[j].append(i)
            if s[i - 1] == s[j - 1]:
                graph[i].append(j)
                graph[j].append(i)

    largest_diameter = 0
    for v1, v2 in combinations(iter(adjacency.keys()), 2):
        diameter = 1 + max(diameter_of_two_graph_class(graph, v1), diameter_of_two_graph_class(graph, v2))
        largest_diameter = max(largest_diameter, diameter)

    n_couples_with_diameter = 0
    for v1, adj in adjacency.items():
        for v2 in adj:
            if diameter_of_two_graph_class(graph, v1) == largest_diameter:
                n_couples_with_diameter += 1

    return largest_diameter, n_couples_with_diameter

def diameter_of_two_graph_class(graph, node1: int) -> int:
    queue = [(node1, 0)]
    distances = {}

    while queue:
        node, dist = queue.pop(0)
        if node not in distances:
            distances[node] = dist + 1
            for neighbor in graph[node]:
                queue.append((neighbor, dist + 1))

    return distances

