            if extra_swap_count > allowed_swap_count >= max_swap_count:
                max_swap_count = extra_swap_count
                allowed_swaps = MAX_SWAP - extra_swap_count

        j += 1

    A = A[0:max_swap_count]

    return A, allowed_swaps


def get_next_permutation(A):
    i = len(A) - 1

    while i > 0 and A[i - 1] <= A[i]:
        i -= 1

    if i == 0:
        return [], 0

    t = A[i - 1]
    J = i

    while J < len(A) and A[J] < t:
        J += 1


    T = A[:J]
    Z = A[i - 1]
    H = A[i + 1:]

    A = T + H
    if 0 < J - i:
        A = A[:J - i] + Z + A[i:J] + H[i:]


    return A, T + [Z] + H, J - i


def smallest_permutation(A, swaps_max):
    A, swaps_max = get_next_permutation(A, swaps_max + 2)
