    def get_prefix_sum(self):
        self.prefix_sum = [0]
        for value in self.permutations:
            self.prefix_sum.append(self.prefix_sum[-1] + value)

    def count_possibilities(self, length):
        n = len(self.prefix_sum)
        prefix_sum = self.prefix_sum
        if length * 2 > n:
            return 0
        lower_bound = length // 2
        upper_bound = (length * 2 - 1) // 2
        left_sum = 0
        right_sum = 0
        if length % 2 == 1:
            middle_sum = prefix_sum[length // 2]
        else:
            middle_sum = prefix_sum[length // 2] + prefix_sum[-1]
        for i in range(upper_bound):
            left_sum += prefix_sum[i]
            right_sum += prefix_sum[n - length + i]
            if left_sum > middle_sum and (0 <= right_sum <= middle_sum or right_sum < middle_sum):
                return i
        return n - upper_bound

