    if string[0] == '*' or string[n] == '*' or string[n + 1] == '*' or string[2 * n] == '*':
        return mod_if_1
    else:
        value = string[1] if string[n] == '*' else string[2 * n]
        return recurse(string, ((1 << n) - 1) ^ (1 << (len(string) - 1)), 0, 0) % MOD

