def gcdExtended(a, b):
    # a, b != 0
    if b == 0:
        return a, 1, 0
    gcd1, x1, y1 = gcdExtended(b, a % b)
    x = y1
    y = x1 - (a // b) * y1
    return gcd1, x, y

def modinv(num, mod):
    _, x, _ = gcdExtended(num, mod)
    x %= mod
    assert(1 <= x and x <= mod)
    return x

def modpow(x, y, p):
    x = x % p
    res = 1
    m = y
    y = y - 1
    while y > 0:
        if y & 1:
            res = res * x % p
        x = x * x % p
        y = y >> 1
    return res % p

class Monotone:
