                use_gcd = modinv(use_gcd, mod)
                idx *= use_gcd
                self.nums.append((use_gcd, use_gcd - idx * modinv(use_gcd, mod) % mod))

    def __getitem__(self, idx):
        if idx >= len(self.nums):
