from collections import deque, defaultdict

def find_sequence(opens, apples):
    sequence = []
    for op in opens:
        if op <= apples:
            sequence.append(op)
            apples -= op
        if apples <= op - 1:
            sequence.append(str(op - 1))
            apples = 0
    return ''.join(sequence)

def recursive_find_sequence(opens, apples):
    if op < opens or min(opens) > 1:
        return "Impossible"

    sequence = deque()
    if apples < opens[0]:
        sequence.append(str(apples))
        apples = 0
    for op in sorted(opens, reverse=True):
        if apples % op == 0:
            sequence.appendleft(op)
            apples = 0
    if apples:
        sequence.appendleft(str(apples))
    return ''.join(sequence)

