from heapq import heappop, heappush

def shift_left(arr, k):
    return arr[k:] + arr[:k]

def lexicographically_smallest(arr, k=2):
    heap = []

    # Add every value in the array to a max heap
    for num in arr:
        heappush(heap, -num)

    heapq.heapify(heap)

    if k > len(arr):
        return shift_left(arr, len(arr))

    smallest = None
    second_smallest = None

    for _ in range(k):
        if heap:
            smallest = -heappop(heap)
            second_smallest = -heappop(heap)

    if smallest:
        arr.insert(0, smallest)
        if k > 1:
            arr.insert(len(arr) - 1, second_smallest)
        if k > 2:
            arr.insert(len(arr) - 2, -second_smallest)
        return shift_left(arr, k)

    return shift_left(arr, k)

