from collections import defaultdict
from random import randint

MOD = 1000000007
MAX_BALLS_PER_COLOR = 100000
CAN_BE_COLOR = 268435456

class BallStabilityModel:
    def __init__(self):
        self.ball_counts_by_color = defaultdict(int)
        self.expected_time = 0

    def add_ball(self, color, count):
        self.ball_counts_by_color[color] += count
        self.expected_time += count

    def simulate_ball_swap(self):
        swap_result = (1, 0)
        while swap_result[1]:
            color_1, color_2 = randint(1, CAN_BE_COLOR), randint(1, CAN_BE_COLOR)
            if self.ball_counts_by_color[color_2] > 1:
                if self.ball_counts_by_color[color_2] - 1 > 0:
                    self.ball_counts_by_color[color_1] -= 1
                    self.ball_counts_by_color[color_2] -= 1
                swap_result = (color_1, color_2)
        return swap_result[1]

    def perform_moves(self, n_cross, cross_times):
        self.expected_time = ((self.expected_time + 1) * n_cross) % MOD
        for _ in range(cross_times):
            self.add_ball(randint(1, CAN_BE_COLOR), 1)
            self.simulate_ball_swap()
        return self.expected_time

def calculate_expected_time(n, ball_counts):
    model = BallStabilityModel()
    expected_time = sum(ball_counts) % MOD
    for each_color in ball_counts:
        if each_color:
            steps = model.perform_moves(each_color, 1)
            expected_time += steps * each_color % MOD
            expected_time -= steps * each_color // CAN_BE_COLOR % MOD
    expected_time %= MOD
    return expected_time

import math

def main():
    n = int(input())
    ball_counts = list(map(int, input().split()))
    if min(ball_counts) == 1 and max(ball_counts) == n:
        print(1)
    else:
        print(calculate_expected_time(n, ball_counts) % MOD)

if __name__ == "__main__":
    main()
