import sys

def find_time(max_speed, r, start, finish):
    return (start**2 + r**2)**0.75 + (finish**2 - start**2 + r**2)**0.75 / max_speed

def main():
    n, r, v = map(int, input().split())
    competitions = []

    for _ in range(n):
        si, fi = map(int, input().split())
        competitions.append((si, fi))

    min_times = []

    for si, fi in competitions:
        min_time = float('inf')
        i = 1
        while True:
            new_time = find_time(v, r, si, fi)
            if new_time <= min_time:
                min_time = new_time
                if i == 1:
                    j = max(1, (fi - si) // 1)
                else:
                    j = max(1, (fi - si) // 1)
                gap = fi - j
                if si < gap <= fi or fi - r < si <= fi:
                    break
            i *= 2

        for _ in range(i // 2):
            if max(1, si + j + 1 * max(r, v) // (v + r)) < fi:
                min_time -= (j + 2*r + fi - max(r, v))
            elif max(1, si + j) < fi:
                min_time -= j - 1 * max(v, r)
            if si >= fi:
                break
            si += 1
        min_times.append(min_time)

    for min_time in min_times:
        print(f"{min_time:.10f}")

if __name__ == "__main__":
    main()
