from collections import deque

def bfs(graph, start, coloring):
    color_options = {1, 2, 3, 4}
    queue = deque([start])
    visited = set()
    while queue:
        current = queue.popleft()
        for neighbor in get_neighbors(graph, current):
            if neighbor not in visited:
                if neighbor in coloring and coloring[neighbor] not in color_options:
                    print(neighbor)
                    return
                elif neighbor not in color_options:
                    if get_next_color(neighbor, coloring, graph) not in color_options:
                        continue
                coloring[neighbor] = get_next_color(neighbor, coloring, graph)
                color_options.remove(get_next_color(neighbor, coloring, graph))
                if neighbor not in visited:
                    queue.append(neighbor)
                    visited.add(neighbor)
    exit()

def get_neighbors(graph, vertex):
    return [graph[(row, col)] for col in range(vertex.width) for row in range(vertex.height) if vertex[(row, col)] != 0]

def get_next_color(vertex, coloring, graph):
    color_options = {1, 2, 3, 4}
    for neighbor in get_neighbors(graph, vertex):
        if neighbor in coloring:
            if coloring[neighbor] in color_options:
                color_options.remove(coloring[neighbor])
    return max(color_options)

class Vertex:
    def __init__(self, height, width):
        self.height = height
        self.width = width
        self.coloring = dict()

