    lucky_stats = [0] * 10001  # Array to count counts of each number

    for i in range(n * 10 + 1):  # Queue large enough for all numbers up to 10^4
        lucky_nums.append(i)

    for operation in operations:
        command, *params = operation.split()
        l, r = [int(x) - 1 for x in params]

        if command == "count":
