from itertools import combinations_with_replacement

c = int(input())
n = int(input())
coins = [int(input()) for _ in range(n)]

def find_min_coins_to_fail(c, coins, n):
    coin_combinations = combinations_with_replacement(coins, n)

    for combination in sorted(coin_combinations, key=lambda x: sum(x)):
        total = sum(combination)
        if total <= c:
            break
        else:
            total -= max(combination)
            for remaining in combinations_with_replacement(coins, sum(combination) - c):
                total2 = total + sum(remaining)
                if total2 <= c:
                    return total2
    return "Greed is good"

print(find_min_coins_to_fail(c, coins, n))
