import itertools

def find_coloring(n: int, m: int, grid: str) -> str:
    # Determine possible colors for the first column
    if grid[0] != '0':
        for color_1 in list(itertools.permutations(range(1, 5))):
            if all(color_1[grid.index('1') - 1] == color_i for color_i in color_1):
                ids = [x for i, x in enumerate(grid) if x == '0']
                return ''.join(itertools.zip_longest(ids, color_1, fillvalue='0'))
    return '0'

